        <kbd class="txt-xx-small hide-on-touch">m</kbd>
      <% end %>
      <%= render collection: @assigned_to, partial: "user", locals: { card: @card } %>
      <% @users.each do |user| %>
        <%= render "user", card: @card, user: user, data: { assignment_limit_target: "unassigned" } %>
      <% end %>
